module TopModule (
    input  logic clk,
    input  logic j,
    input  logic k,
    output logic Q
);

  always_ff @(posedge clk) begin
    case ({j, k})
      2'b00: Q <= Q;
      2'b01: Q <= 1'b0;
      2'b10: Q <= 1'b1;
      2'b11: Q <= ~Q;
    endcase
  end

endmodule

